const listings=[{id:1,name:'Северный парк · 12—04',district:'Центральный район',rooms:2,area:78,floor:'12 из 24',price:38500000,status:'Доступна',image:'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=900&q=85'},{id:2,name:'Северный парк · 08—07',district:'Центральный район',rooms:3,area:112,floor:'8 из 24',price:57900000,status:'Доступна',image:'https://images.unsplash.com/photo-1600566753190-17f0baa2a6c3?auto=format&fit=crop&w=900&q=85'},{id:3,name:'Берег · 03—02',district:'Набережная',rooms:1,area:48,floor:'3 из 18',price:24900000,status:'Последняя',image:'https://images.unsplash.com/photo-1600607688969-a5bfcd646154?auto=format&fit=crop&w=900&q=85'},{id:4,name:'Берег · 15—01',district:'Набережная',rooms:4,area:146,floor:'15 из 18',price:84500000,status:'Доступна',image:'https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=900&q=85'},{id:5,name:'Дом 12 · 05—09',district:'Исторический район',rooms:2,area:69,floor:'5 из 12',price:42900000,status:'Бронь',image:'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=900&q=85'},{id:6,name:'Дом 12 · 10—03',district:'Исторический район',rooms:3,area:98,floor:'10 из 12',price:65800000,status:'Доступна',image:'https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=900&q=85'}];const saved=new Set(JSON.parse(localStorage.getItem('sq-favs')||'[]'));const rub=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';function render(){const q=document.querySelector('#search').value.toLocaleLowerCase('ru'),room=document.querySelector('#rooms').value,sort=document.querySelector('#sort').value;let list=listings.filter(x=>(room==='all'||String(x.rooms)===room)&&(!q||(x.name+' '+x.district).toLocaleLowerCase('ru').includes(q)));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);document.querySelector('#count').textContent='Показано: '+list.length+' из '+listings.length+' · цены демо';document.querySelector('#homes').innerHTML=list.map(x=>'<article class="home"><div class="home-photo" style="background-image:url('+JSON.stringify(x.image)+')"><span class="status">'+x.status+' · демо</span><button class="fav '+(saved.has(x.id)?'on':'')+'" data-fav="'+x.id+'" aria-label="Добавить в избранное">'+(saved.has(x.id)?'♥':'♡')+'</button></div><div class="home-info"><h3>'+x.name+'</h3><p>'+x.district+' · данные для макета</p><div class="facts"><span>'+x.rooms+' комн.</span><span>'+x.area+' м²</span><span>'+x.floor+'</span></div><div class="price">'+rub(x.price)+' <small>пример</small></div><div class="home-actions"><button class="view" data-view="'+x.id+'">Подробнее</button><button data-fav="'+x.id+'">'+(saved.has(x.id)?'♥ В избранном':'♡ В избранное')+'</button></div></div></article>').join('')||'<p>По вашему запросу ничего не найдено.</p>'}document.querySelector('#homes').addEventListener('click',e=>{const f=e.target.closest('[data-fav]');if(f){const id=Number(f.dataset.fav);saved.has(id)?saved.delete(id):saved.add(id);localStorage.setItem('sq-favs',JSON.stringify([...saved]));render()}const v=e.target.closest('[data-view]');if(v){const x=listings.find(a=>a.id===Number(v.dataset.view));document.querySelector('#modal-title').textContent=x.name;document.querySelector('#modal-facts').textContent=x.district+' · '+x.rooms+' комн. · '+x.area+' м² · этаж '+x.floor;document.querySelector('#modal-price').textContent=rub(x.price)+' · демо';document.querySelector('#modal-img').src=x.image;document.querySelector('#modal-img').alt='Интерьер, иллюстрация для демо-карточки';document.querySelector('#modal').classList.add('open')}});['#search','#rooms','#sort'].forEach(s=>document.querySelector(s).addEventListener(s==='#search'?'input':'change',render));document.querySelector('#close').onclick=()=>document.querySelector('#modal').classList.remove('open');document.querySelector('#modal').addEventListener('click',e=>{if(e.target.id==='modal')e.currentTarget.classList.remove('open')});document.querySelector('#modal-cta').onclick=()=>{document.querySelector('#modal').classList.remove('open');document.querySelector('#contacts').scrollIntoView({behavior:'smooth'});document.querySelector('#form-note').textContent='Демо: выбор квартиры не отправлен. CRM/API не подключены.'};function calculate(){const cost=Number(document.querySelector('#amount').value)||0,down=Math.min(90,Math.max(0,Number(document.querySelector('#down').value)||0)),rate=(Number(document.querySelector('#rate').value)||0)/1200,months=Math.max(1,(Number(document.querySelector('#years').value)||1)*12),loan=cost*(1-down/100),pay=rate?loan*rate/(1-Math.pow(1+rate,-months)):loan/months;document.querySelector('#payment').textContent=rub(Math.round(pay));document.querySelector('#loan-note').textContent='Сумма кредита: '+rub(Math.round(loan))+' · '+months+' месяцев. Ориентировочная аннуитетная формула, исключительно для демонстрации.'}['#amount','#down','#rate','#years'].forEach(s=>document.querySelector(s).addEventListener('input',calculate));document.querySelector('#lead').addEventListener('submit',e=>{e.preventDefault();document.querySelector('#form-note').textContent='Проверка пройдена в браузере. Сообщение НЕ отправлено: сервер и CRM не подключены.'});render();calculate();